Rules.InvariantScript:
If(
    IsBlank(DropDown.Selected.'Beach Names'),
    Notify("Please select a beach", NotificationType.Error),
    Set(varBeach, LookUp(BeachDetails, Title = DropDown.Selected.'Beach Names'));
    Notify("Beach selected!", NotificationType.Success)
)

If(
    IsBlank(varBeach),
    Notify("Please select a beach first", NotificationType.Error),
    IsBlank(OpensTime.Text) Or IsBlank(ClosesTime.Text),
    Notify("Please enter both opening and closing times", NotificationType.Error),
    TimeValue(OpensTime.Text) >= TimeValue(ClosesTime.Text),
    Notify("Opening time must be before closing time", NotificationType.Error),
    Patch(
        BeachDetails,
        varBeach,
        {
            Opens: OpensTime.Text,
            Closes: ClosesTime.Text
        }
    );
    Notify("Beach timings updated!", NotificationType.Success);
    Set(varBeach, LookUp(BeachDetails, Email = EmailInput_1.Text));
    Navigate('Beach-Page 2')
)
